-- The login banner and the minimap tooltip.
L["Click to open the settings"] = "Haz clic para abrir la configuración";
L["Circular class, spec and role icons on every nameplate, live crowd-control icons and instant Healer CC alerts."] = "Iconos circulares de clase, especialización y rol en cada placa de nombre, iconos de control en directo y avisos instantáneos de control sobre el sanador.";
L["OPlates only adds icons. Your nameplate addon keeps its own bars and style."] = "OPlates solo añade iconos. Tu addon de placas de nombre conserva sus propias barras y estilo.";
L["Type %s or click the minimap button to open the settings."] = "Escribe %s o haz clic en el botón del minimapa para abrir la configuración.";
L["Open settings"] = "Abrir configuración";
L["Test"] = "Prueba";
L["Hide"] = "Ocultar";

-- The settings window.
L["|cffff3b3bWARMANE AND OTHER SERVERS THAT FORBID CLIENT MODIFICATIONS ARE NOT COMPATIBLE WITH awesome_wotlk OR ANY CLIENT PATCH. DO NOT INSTALL IT THERE.|r"] = "|cffff3b3bWARMANE Y OTROS SERVIDORES QUE PROHÍBEN LAS MODIFICACIONES DEL CLIENTE NO SON COMPATIBLES CON awesome_wotlk NI CON NINGÚN PARCHE DE CLIENTE. NO LO INSTALES ALLÍ.|r";
L["Your client is unpatched, so players reveal their class only after you mouseover them. The free FreakySphere awesome_wotlk client patch gives every visible player class colors, icons and borders instantly, with no mouseover at all. Copy the link below if you want it. OPlates runs fine without it."] = "Tu cliente no está parcheado, así que los jugadores revelan su clase solo cuando pasas el ratón por encima. El parche de cliente gratuito awesome_wotlk de FreakySphere da a cada jugador visible colores de clase, iconos y bordes al instante, sin pasar el ratón. Copia el enlace de abajo si lo quieres. OPlates funciona perfectamente sin él.";
L["OPlates now reads nameplate units straight from your client: every visible player gets class colors, icons and borders instantly, no mouseover needed. You can switch this off in /op > Advanced."] = "OPlates ahora lee las unidades de placa de nombre directamente de tu cliente: cada jugador visible recibe colores de clase, iconos y bordes al instante, sin pasar el ratón. Puedes desactivarlo en /op > Avanzado.";
L["Your client has the awesome_wotlk patch, but OPlates is not using its nameplate units, so you are missing instant class colors, icons and borders on every visible player. Turn it on now?"] = "Tu cliente tiene el parche awesome_wotlk, pero OPlates no usa sus unidades de placa de nombre, así que te faltan los colores de clase, iconos y bordes instantáneos en cada jugador visible. ¿Activarlo ahora?";
L["|cffff3b3bWarmane: patch not allowed|r"] = "|cffff3b3bWarmane: parche no permitido|r";
